const envelope = $input || {};
const text = (value) => (typeof value === 'string' ? value.trim() : '');
const envelopeKeys = new Set(['pluginId', 'widgetId', 'product', 'resource', 'submittedBy', 'submittedAt', 'action', 'fields']);
const unknownEnvelope = Object.keys(envelope).filter((key) => !envelopeKeys.has(key));
if (unknownEnvelope.length) throw new Error('unknown_envelope_fields:' + unknownEnvelope.join(','));
const product = text(envelope.product);
const resource = text(envelope.resource);
const submittedBy = text(envelope.submittedBy);
if (!submittedBy) throw new Error('submitted_by_required');
const fields = envelope.fields && typeof envelope.fields === 'object' && !Array.isArray(envelope.fields) ? envelope.fields : null;
if (!fields) throw new Error('fields_required');

if (product !== 'sos') throw new Error('unsupported_product');
if (resource !== 'dispatch') throw new Error('unsupported_resource');
const orderId = text(fields.order_id);
if (!/^[A-Za-z0-9_@.:+-]{1,256}$/.test(orderId)) throw new Error('record_id_invalid');
const approvalId = text(fields.approval_id);
if (!/^[A-Za-z0-9_@.:+-]{1,256}$/.test(approvalId)) throw new Error('approval_id_invalid');
const resourceId = text(fields.assigned_resource_unit_id);
if (!/^[A-Za-z0-9_@.:+-]{1,256}$/.test(resourceId)) throw new Error('assigned_resource_unit_id_required');
const allowed = new Set(['order_id', 'approval_id', 'assigned_resource_unit_id', 'eta_minutes', 'notes']);
const unknown = Object.keys(fields).filter((key) => !allowed.has(key));
if (unknown.length) throw new Error('unknown_fields:' + unknown.join(','));
let etaMinutes;
if (fields.eta_minutes !== undefined && fields.eta_minutes !== null && String(fields.eta_minutes).trim() !== '') {
  const num = Number(fields.eta_minutes);
  if (!Number.isFinite(num) || num < 0) throw new Error('eta_minutes_invalid');
  etaMinutes = num;
}
const notes = text(fields.notes);
if (notes.length > 4000) throw new Error('notes_max_4000');
const audit = {
  product, resource, operation: 'dispatch.assign', recordId: orderId,
  pluginId: text(envelope.pluginId), widgetId: text(envelope.widgetId),
  submittedBy, submittedAt: text(envelope.submittedAt) || $now,
};
return {
  orderId, encodedOrderId: encodeURIComponent(orderId), planId: orderId,
  approvalId, encodedApprovalId: encodeURIComponent(approvalId),
  resourceId, encodedResourceId: encodeURIComponent(resourceId),
  etaMinutes, notes, audit,
};

const response = $input || {};
const state = response.input;
if (response.statusCode !== 200 || !response.body || typeof response.body !== 'object') throw new Error('approval_not_found');
const approval = response.body.approval && typeof response.body.approval === 'object' ? response.body.approval : response.body;
if (String(approval.status) !== 'approved') throw new Error('approval_not_approved');
if (String(approval.entityId) !== String(state.planId)) throw new Error('approval_entity_mismatch');
if (String(approval.action) !== 'dispatch.assign') throw new Error('approval_action_mismatch');
// Four-eyes (docs/HITL.md, mirroring assert_approval_ready in the Tier-3
// routes): the operator who requested the approval can never consume it.
if (String(approval.requester) === String(state.audit.submittedBy)) throw new Error('self_approval_forbidden');
return { ...state, approval: { id: approval.id === undefined ? null : String(approval.id), approverRoles: Array.isArray(approval.approverRoles) ? approval.approverRoles.map(String) : [] } };

const response = $input || {};
const state = response.input;
const current = response.body;
if (response.statusCode !== 200 || !current || typeof current.data !== 'object' || !current.data) throw new Error('order_not_found');
if (!Number.isInteger(current.version)) throw new Error('record_version_unavailable');
const order = { ...current.data, id: String(current.data.id || current.id) };
return { ...state, order, version: current.version };

const response = $input || {};
const state = response.input;
const current = response.body;
if (response.statusCode !== 200 || !current || typeof current.data !== 'object' || !current.data) throw new Error('resource_unit_not_found');
if (!Number.isInteger(current.version)) throw new Error('record_version_unavailable');
const unit = { ...current.data, id: String(current.data.id || current.id) };
const order = state.order;
const orderStatus = String(order.status);
const requested = String(state.resourceId);
if (['completed', 'canceled', 'rejected'].includes(orderStatus)) {
  const reservedForThisOrder = String(unit.status) === 'assigned' && String(unit.assigned_dispatch_order_id || '') === String(order.id);
  if (reservedForThisOrder) return { ...state, unit, unitVersion: current.version, mode: 'compensate' };
  throw new Error('order_terminal');
}
const existing = typeof order.assigned_resource_unit_id === 'string' && order.assigned_resource_unit_id.trim() ? order.assigned_resource_unit_id.trim() : '';
if (existing) {
  if (existing !== requested) throw new Error('order_already_assigned');
  if (orderStatus === 'assigned') return { ...state, unit, unitVersion: current.version, mode: 'idempotent' };
  throw new Error('invalid_dispatch_status');
}
if (!['pending', 'approved'].includes(orderStatus)) throw new Error('invalid_dispatch_status');
const unitStatus = String(unit.status || '');
const alreadyReserved = unitStatus === 'assigned' && String(unit.assigned_dispatch_order_id || '') === String(order.id);
if (!alreadyReserved && unitStatus !== 'available') throw new Error('resource_unit_unavailable');
return { ...state, unit, unitVersion: current.version, mode: alreadyReserved ? 'reserved' : 'reserve' };

const state = $input || {};
if (state.mode !== 'compensate') throw new Error('unexpected_assign_mode');
const next = { ...state.unit, status: 'available', assigned_dispatch_order_id: null, released_at: $now, updated_at: $now };
return { body: { data: next, ifVersion: state.unitVersion }, encodedId: state.encodedResourceId, audit: state.audit, operation: state.operation, resourceId: state.resourceId };

const response = $input || {};
const state = response.input;
if (response.statusCode !== 200 && response.statusCode !== 201) throw new Error('reservation_release_failed_' + response.statusCode);
// Mirror of the dispatch_approve compensation: the reservation is released
// and the terminal order still refuses the assignment.
throw new Error('order_terminal (reserved unit ' + state.resourceId + ' released)');

const state = $input || {};
if (state.mode !== 'idempotent') throw new Error('unexpected_assign_mode');
return { idempotent: true, operation: 'dispatch.assign', order_id: state.order.id, status: 'assigned', assigned_resource_unit_id: state.resourceId, approval_id: state.approval.id };

const state = $input || {};
if (state.mode !== 'reserve') throw new Error('unexpected_assign_mode');
const next = { ...state.unit, status: 'assigned', assigned_dispatch_order_id: String(state.order.id), assigned_at: $now, assigned_by: state.audit.submittedBy, updated_at: $now };
return { ...state, body: { data: next, ifVersion: state.unitVersion } };

const response = $input || {};
const state = response.input;
if (response.statusCode !== 200 && response.statusCode !== 201) throw new Error('resource_unit_conflict');
return { ...state, reserved: true };

const state = $input || {};
if (state.mode !== 'reserved') throw new Error('unexpected_assign_mode');
return { ...state, reserved: true };

const state = $input || {};
const order = state.order;
if (!['reserve', 'reserved'].includes(state.mode)) throw new Error('unexpected_assign_mode');
const now = $now;
const actor = state.audit.submittedBy;
const assignments = Array.isArray(order.assignments) ? [...order.assignments] : [];
const duplicate = assignments.some((assignment) => assignment && typeof assignment === 'object'
  && String(assignment.dispatch_order_id || '') === String(order.id)
  && String(assignment.assigned_resource_unit_id || assignment.resource_unit_id || '') === String(state.resourceId));
if (!duplicate) {
  assignments.push({
    dispatch_order_id: String(order.id),
    resource_unit_id: String(state.resourceId),
    assigned_resource_unit_id: String(state.resourceId),
    assigned_user_id: String(state.resourceId),
    assigned_at: now,
    assigned_by: actor,
  });
}
const next = {
  ...order,
  status: 'assigned',
  assigned_resource_unit_id: String(state.resourceId),
  assigned_user_id: String(state.resourceId),
  assigned_at: now,
  assigned_by: actor,
  assignments,
  approval_id: state.approval.id,
  approved_by: actor,
  approval_roles: state.approval.approverRoles,
  approved_at: now,
  updated_at: now,
};
if (state.etaMinutes !== undefined && state.etaMinutes !== null) next.eta_minutes = state.etaMinutes;
if (state.notes) next.notes = state.notes;
return { body: { data: next, ifVersion: state.version }, encodedId: state.encodedOrderId, audit: state.audit, operation: state.operation };
